contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function with inputs: amount to send to c.go
    function run(uint amount) public payable {
        require(address(this).balance >= amount, "insufficient balance to send");

        // read owner before call via public getter
        address ownerBefore = c.owner();
        // read contract balance before
        uint balBefore = address(c).balance;

        // perform the state-changing call on c: send Ether to c.go
        bool didRevert;
        try c.go{value: amount}() {
            didRevert = false;
        } catch {
            didRevert = true;
        }

        // observe after values
        address ownerAfter = c.owner();
        uint balAfter = address(c).balance;

        // If the call did not revert, then all Ether that was in C after the call must be zero
        // and the owner must remain unchanged. If it reverted, we make no claim about balances but still
        // require owner unchanged because go does not modify owner even on revert.
        assert(ownerBefore == ownerAfter && (didRevert || balAfter == 0));
    }

    // contract must be able to receive refunds/transfers during calls
    receive() external payable {}
}

contract InvMutTest {
    C c;
    address beforeOwner;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        // record observable before-state
        beforeOwner = c.owner();
        bool reverted;
        // attempt to call go forwarding `amount` wei
        try c.go{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        // After the call: either it reverted, or c must have zero balance and same owner
        assert(reverted || (address(c).balance == 0 && c.owner() == beforeOwner));
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function taking an amount to forward to c.go
    function run(uint amount) public payable {
        // If we will send Ether, ensure the test contract has it
        require(address(this).balance >= amount);

        // observe owner before
        address ownerBefore = c.owner();
        // observe balances before
        uint cBalBefore = address(c).balance;
        uint myBalBefore = address(this).balance;

        bool reverted;
        // perform the state-changing call as its own top-level statement
        try c.go{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe owner and balances after
        address ownerAfter = c.owner();
        uint cBalAfter = address(c).balance;
        uint myBalAfter = address(this).balance;

        // General rule asserted for all inputs: owner never changes; if call succeeded then C's balance is zero and this test's balance did not increase (no Ether leaked to caller)
        assert(ownerBefore == ownerAfter && (reverted || (cBalAfter == 0 && myBalAfter <= myBalBefore)));
    }

    // allow receiving Ether if target forwards to us during execution
    receive() external payable {}
}

